import { useCallback, useEffect, useState } from "react";
import { ExternalLink, FileCode, Globe, List, Lock, LockOpen, Play, Plus, Puzzle, RefreshCw, Square } from "lucide-react";
// @ts-ignore wailsjs bindings are generated by wails build
import {
  CreateKinds,
  CreateProject,
  ListPhpExtensions,
  GetProjectVhost,
  GetTLD,
  ListPhpSeries,
  ListProjects,
  OpenProjectURL,
  Rescan,
  SaveProjectVhost,
  SetPhpExtension,
  SetProjectsTLD,
  SetProjectPhp,
  SetProjectSSL,
} from "../../wailsjs/go/controllers/Projects";
// @ts-ignore wailsjs bindings are generated by wails build
import {
  GetQueueWorkerLogs,
  GetQueueWorkerStatus,
  RestartQueueWorker,
  StartQueueWorker,
  StopQueueWorker,
} from "../../wailsjs/go/controllers/CronQueue";
// @ts-ignore wailsjs bindings are generated by wails build
import { EventsOn } from "../../wailsjs/runtime";
import DocumentEditor from "../components/documents/DocumentEditor";
import { useDialogs } from "../components/dialogs/DialogProvider";
import { useT } from "../lib/i18n";

type ProjectRow = {
  name: string;
  kind: string;
  ssl: boolean;
  url: string;
  phpSeries?: string;
  phpSource?: string;
  phpProblem?: string;
  phpInstallTip?: string;
  nodeVersion?: string;
  jsFramework?: string;
  packageManager?: string;
};

export default function Projects() {
  const t = useT();
  const dialogs = useDialogs();
  const [rows, setRows] = useState<ProjectRow[]>([]);
  const [series, setSeries] = useState<string[]>([]);
  const [tld, setTld] = useState("test");
  const [tldDraft, setTldDraft] = useState("test");
  const [busy, setBusy] = useState<string | null>(null);
  const [showCreate, setShowCreate] = useState(false);
  const [vhost, setVhost] = useState<{ name: string; content: string; dirty: boolean } | null>(null);
  const [extensions, setExtensions] = useState<{ series: string } | null>(null);

  const refresh = useCallback(() => {
    ListProjects().then((list: ProjectRow[]) => setRows(list ?? [])).catch(() => { /* pre-startup */ });
    ListPhpSeries().then((list: string[]) => setSeries(list ?? [])).catch(() => { /* none */ });
    GetTLD().then((value: string) => {
      setTld(value);
      setTldDraft(value);
    }).catch(() => { /* default */ });
  }, []);

  useEffect(() => {
    refresh();
    // @ts-ignore EventsOn returns a cancel function
    return EventsOn("project:changed", () => refresh());
  }, [refresh]);

  useEffect(() => {
    // @ts-ignore EventsOn returns a cancel function
    return EventsOn("project:error", async (payload: { name: string; message: string }) => {
      await dialogs.alert({ title: payload.name, message: payload.message });
    });
  }, [dialogs]);

  const toggleSSL = async (row: ProjectRow) => {
    setBusy(row.name + "ssl");
    try {
      await SetProjectSSL(row.name, !row.ssl);
    } catch (error) {
      await dialogs.alert({ title: row.name, message: String(error) });
    } finally {
      setBusy(null);
      refresh();
    }
  };

  const pickPhp = async (row: ProjectRow) => {
    const options = ["", ...series];
    const current = row.phpSource === "manual" ? row.phpSeries : "";
    const next = await dialogs.prompt({
      title: `${row.name} · PHP`,
      message: options.length > 1
        ? t("projects.phpPickHelp", { series: series.join(", ") })
        : t("projects.phpPickEmpty"),
      label: t("projects.phpPickLabel"),
      defaultValue: current,
    });
    if (next === null) return;
    const value = next.trim();
    if (value !== "" && !series.includes(value)) {
      await dialogs.alert({ title: row.name, message: t("projects.phpUnknown", { series: value }) });
      return;
    }
    setBusy(row.name + "php");
    try {
      await SetProjectPhp(row.name, value);
    } catch (error) {
      await dialogs.alert({ title: row.name, message: String(error) });
    } finally {
      setBusy(null);
      refresh();
    }
  };

  const changeTld = async () => {
    const value = tldDraft.trim().replace(/^\.+|\.+$/g, "");
    if (value === "" || value === tld) {
      setTldDraft(tld);
      return;
    }
    const yes = await dialogs.confirm({
      title: t("projects.tldConfirmTitle", { tld: value }),
      message: t("projects.tldConfirmBody"),
    });
    if (!yes) {
      setTldDraft(tld);
      return;
    }
    try {
      await SetProjectsTLD(value);
    } catch (error) {
      await dialogs.alert({ title: t("projects.tldTitle"), message: String(error) });
    }
    refresh();
  };

  const openVhost = async (row: ProjectRow) => {
    try {
      const file = await GetProjectVhost(row.name);
      setVhost({ name: row.name, content: file.content, dirty: false });
    } catch (error) {
      await dialogs.alert({ title: row.name, message: String(error) });
    }
  };

  return (
    <div className="space-y-4">
      <header className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-lg font-semibold text-white/95">{t("projects.title")}</h1>
          <p className="text-xs text-white/50">{t("projects.subtitle")}</p>
        </div>
        <div className="flex items-center gap-2">
          <label className="flex items-center gap-1.5 text-xs text-white/55">
            {t("projects.tld")}
            <input
              className="input w-24 py-1"
              value={tldDraft}
              spellCheck={false}
              onChange={(event) => setTldDraft(event.target.value)}
              onBlur={changeTld}
              onKeyDown={(event) => {
                if (event.key === "Enter") event.currentTarget.blur();
              }}
            />
          </label>
          <button
            type="button"
            onClick={() => refresh()}
            title={t("common.retry")}
            className="rounded-md border border-white/10 bg-white/5 p-1.5 text-white/60 hover:bg-white/10 hover:text-white"
          >
            <RefreshCw className="h-3.5 w-3.5" />
          </button>
          <button
            type="button"
            onClick={() => setShowCreate(true)}
            className="flex items-center gap-1.5 rounded-md bg-accent px-3 py-1.5 text-xs font-medium text-white hover:bg-accent/85"
          >
            <Plus className="h-3.5 w-3.5" /> {t("projects.new.button")}
          </button>
        </div>
      </header>

      {showCreate && (
        <NewProjectModal
          onClose={() => setShowCreate(false)}
          onDone={() => {
            setShowCreate(false);
            refresh();
          }}
        />
      )}
      {extensions && (
        <ExtensionsModal series={extensions.series} onClose={() => setExtensions(null)} />
      )}
      {vhost && <VhostModal name={vhost.name} content={vhost.content} dirty={vhost.dirty} onChange={(c) => setVhost((v) => (v ? { ...v, content: c, dirty: true } : v))} onClose={() => setVhost(null)} />}

      {rows.length === 0 ? (
        <section className="glass p-8 text-center">
          <p className="text-sm font-medium text-white/80">{t("projects.empty.title")}</p>
          <p className="mt-1 text-xs text-white/50">{t("projects.empty.body")}</p>
        </section>
      ) : (
        <div className="grid grid-cols-1 gap-2 md:grid-cols-2">
          {rows.map((row) => (
            <article key={row.name} className="glass flex flex-col gap-2.5 p-4">
              <div className="flex items-start justify-between gap-2">
                <div className="min-w-0">
                  <h3 className="truncate text-sm font-semibold text-white/90">{row.name}</h3>
                  <div className="mt-0.5 flex flex-wrap items-center gap-1.5 text-[10px]">
                    <span className="rounded-full border border-white/15 px-2 py-0.5 uppercase text-white/50">{row.kind}</span>
                    {row.jsFramework && (
                      <span className="rounded-full border border-accent2/40 px-2 py-0.5 text-accent2">{row.jsFramework}</span>
                    )}
                    {row.packageManager && (
                      <span className="rounded-full border border-white/15 px-2 py-0.5 text-white/45">{row.packageManager}</span>
                    )}
                  </div>
                </div>
                <div className="flex shrink-0 items-center gap-1">
                              {row.phpSeries && (
              <button
                type="button"
                onClick={() => setExtensions({ series: row.phpSeries! })}
                title={t("projects.extensions.title") + " · PHP " + row.phpSeries}
                className="rounded border border-white/10 bg-white/5 p-1.5 text-white/60 hover:bg-white/10 hover:text-white"
              >
                <Puzzle className="h-3.5 w-3.5" />
              </button>
            )}
            <button
              type="button"
              onClick={() => void openVhost(row)}
              title={t("projects.vhost.edit")}
              className="rounded border border-white/10 bg-white/5 p-1.5 text-white/60 hover:bg-white/10 hover:text-white"
            >
              <FileCode className="h-3.5 w-3.5" />
            </button>
<button
                    type="button"
                    onClick={() => void toggleSSL(row)}
                    disabled={busy !== null}
                    title={row.ssl ? t("projects.sslOff") : t("projects.sslOn")}
                    className={`rounded-md border p-1.5 disabled:opacity-40 ${
                      row.ssl
                        ? "border-emerald-400/40 bg-emerald-400/10 text-emerald-300"
                        : "border-white/10 bg-white/5 text-white/50 hover:bg-white/10"
                    }`}
                  >
                    {row.ssl ? <Lock className="h-3.5 w-3.5" /> : <LockOpen className="h-3.5 w-3.5" />}
                  </button>
                  <button
                    type="button"
                    onClick={() => void OpenProjectURL(row.name)}
                    title={row.url}
                    className="rounded-md border border-white/10 bg-white/5 p-1.5 text-white/60 hover:bg-white/10 hover:text-white"
                  >
                    <ExternalLink className="h-3.5 w-3.5" />
                  </button>
                </div>
              </div>

              <div className="flex flex-wrap items-center gap-2 text-[11px]">
                <button
                  type="button"
                  onClick={() => void pickPhp(row)}
                  className={`rounded-md border px-2 py-1 font-mono ${
                    row.phpProblem
                      ? "border-amber-400/40 bg-amber-400/10 text-amber-300"
                      : "border-white/10 bg-white/5 text-white/75 hover:bg-white/10"
                  }`}
                >
                  PHP {row.phpSeries || "—"}
                  {row.phpSource === "manual" ? " 📌" : ""}
                </button>
                {row.nodeVersion && (
                  <span className="rounded-md border border-white/10 bg-white/5 px-2 py-1 font-mono text-white/75">
                    node {row.nodeVersion}
                  </span>
                )}
                <button
                  type="button"
                  onClick={() => void Rescan(row.name)}
                  title={t("projects.rescan")}
                  className="ml-auto rounded-md border border-white/10 px-2 py-1 text-white/50 hover:bg-white/10 hover:text-white"
                >
                  <Globe className="mr-1 inline h-3 w-3" />
                  {row.name}.{tld}
                </button>
              </div>

              {row.phpProblem && (
                <p className="text-[10px] leading-relaxed text-amber-300/80">
                  {row.phpProblem}
                  {row.phpInstallTip && ` · ${t("projects.phpInstallTip", { series: row.phpInstallTip })}`}
                </p>
              )}

              {row.kind === "laravel" && (
                <QueueWorkerControls projectName={row.name} />
              )}
            </article>
          ))}
        </div>
      )}
    </div>
  );
}

// --- Queue Worker Controls --------------------------------------------------------

type QueueStatus = { running: boolean; pid?: number; args?: string };

function QueueWorkerControls({ projectName }: { projectName: string }) {
  const t = useT();
  const dialogs = useDialogs();
  const [status, setStatus] = useState<QueueStatus>({ running: false, pid: 0, args: "" });
  const [logs, setLogs] = useState<string[]>([]);
  const [showLogs, setShowLogs] = useState(false);
  const [args, setArgs] = useState("");

  const refresh = useCallback(() => {
    GetQueueWorkerStatus(projectName).then((s: QueueStatus) => setStatus(s)).catch(() => { /* pre-startup */ });
  }, [projectName]);

  useEffect(() => {
    refresh();
    // @ts-ignore EventsOn returns a cancel function
    return EventsOn("queueworker:status", (s: { project: string }) => {
      if (s?.project === projectName) refresh();
    });
  }, [refresh, projectName]);

  useEffect(() => {
    if (!showLogs) return;
    const timer = window.setInterval(() => {
      GetQueueWorkerLogs(projectName).then((l: string[]) => setLogs(l ?? [])).catch(() => { /* dead */ });
    }, 1200);
    return () => window.clearInterval(timer);
  }, [showLogs, projectName]);

  const start = async () => {
    try {
      await StartQueueWorker(projectName, args);
    } catch (error) {
      await dialogs.alert({ title: projectName, message: String(error) });
    }
    refresh();
  };

  const stop = async () => {
    await StopQueueWorker(projectName);
    refresh();
  };

  const restart = async () => {
    try {
      await RestartQueueWorker(projectName, args);
    } catch (error) {
      await dialogs.alert({ title: projectName, message: String(error) });
    }
    refresh();
  };

  return (
    <div className="flex flex-wrap items-center gap-1.5 border-t border-white/10 pt-2 text-[10px]">
      <span className="text-white/40">{t("projects.queue.title")}</span>
      <span
        className={`h-1.5 w-1.5 rounded-full ${status.running ? "bg-emerald-400" : "bg-white/20"}`}
        title={status.running ? t("projects.queue.running") : t("projects.queue.stopped")}
      />
      {status.running ? (
        <>
          <button
            type="button"
            onClick={() => void stop()}
            className="flex items-center gap-1 rounded border border-white/10 px-1.5 py-0.5 text-white/70 hover:bg-white/10"
          >
            <Square className="h-2.5 w-2.5" /> {t("projects.queue.stop")}
          </button>
          <button
            type="button"
            onClick={() => void restart()}
            className="flex items-center gap-1 rounded border border-white/10 px-1.5 py-0.5 text-white/70 hover:bg-white/10"
          >
            <RefreshCw className="h-2.5 w-2.5" /> {t("projects.queue.restart")}
          </button>
        </>
      ) : (
        <>
          <input
            className="input w-32 py-0.5 text-[10px]"
            placeholder={t("projects.queue.argsPlaceholder")}
            value={args}
            onChange={(e) => setArgs(e.target.value)}
          />
          <button
            type="button"
            onClick={() => void start()}
            className="flex items-center gap-1 rounded border border-accent/40 bg-accent/15 px-1.5 py-0.5 text-accent2 hover:bg-accent/25"
          >
            <Play className="h-2.5 w-2.5" /> {t("projects.queue.start")}
          </button>
        </>
      )}
      <button
        type="button"
        onClick={() => setShowLogs(!showLogs)}
        className="ml-auto flex items-center gap-1 rounded border border-white/10 px-1.5 py-0.5 text-white/50 hover:bg-white/10 hover:text-white"
      >
        <List className="h-2.5 w-2.5" /> {t("projects.queue.logs")}
      </button>
      {showLogs && (
        <pre className="mt-1 max-h-32 w-full overflow-auto rounded bg-black/40 p-2 font-mono text-[9px] leading-relaxed text-white/70">
          {logs.length > 0 ? logs.join("\n") : t("projects.queue.noLogs")}
        </pre>
      )}
    </div>
  );
}


// NewProjectModal scaffolds a project: kind picker over the backend's
// create kinds, name, and the two optional extras (git URL, package
// manager); progress streams from project:create events.
function NewProjectModal({ onClose, onDone }: { onClose: () => void; onDone: () => void }) {
  const t = useT();
  const [kinds, setKinds] = useState<string[]>(["laravel", "wordpress", "git", "vite", "next", "nuxt", "astro", "blank"]);
  const [kind, setKind] = useState("laravel");
  const [name, setName] = useState("");
  const [gitUrl, setGitUrl] = useState("");
  const [pkg, setPkg] = useState("npm");
  const [running, setRunning] = useState(false);
  const [log, setLog] = useState<string[]>([]);

  useEffect(() => {
    const timer = setTimeout(() => {
      CreateKinds()
        .then((list: string[]) => {
          if (list && list.length > 0) {
            setKinds(list);
            setKind(list[0]);
          }
        })
        .catch(() => {});
    }, 0);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    // @ts-ignore EventsOn returns a cancel function
    return EventsOn("project:create", (p: { line?: string; error?: string; done?: boolean }) => {
      setLog((prev) => [...prev.slice(-200), p.line ?? p.error ?? (p.done ? "✓" : "")]);
    });
  }, []);

  const jsKind = ["vite", "next", "nuxt", "astro"].includes(kind);

  const submit = async () => {
    setRunning(true);
    setLog([]);
    try {
      await CreateProject({ name, kind, gitUrl, packageManager: jsKind ? pkg : "" });
      onDone();
    } catch {
      /* error lines already streamed into the log */
    } finally {
      setRunning(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50" onClick={running ? undefined : onClose}>
      <section className="glass w-[520px] max-w-[92vw] space-y-3 rounded-xl p-4" onClick={(e) => e.stopPropagation()}>
        <h2 className="text-sm font-semibold text-white/90">{t("projects.new.title")}</h2>
        <div className="grid grid-cols-2 gap-3">
          <label className="space-y-1 text-xs">
            <span className="text-white/60">{t("projects.new.kind")}</span>
            <select className="input w-full" value={kind} onChange={(e) => setKind(e.target.value)}>
              {kinds.map((k) => (
                <option key={k} value={k}>{t(`projects.new.kinds.${k}`)}</option>
              ))}
            </select>
          </label>
          <label className="space-y-1 text-xs">
            <span className="text-white/60">{t("projects.new.name")}</span>
            <input className="input w-full font-mono" value={name} onChange={(e) => setName(e.target.value)} placeholder="shop" />
          </label>
        </div>
        {kind === "git" && (
          <label className="block space-y-1 text-xs">
            <span className="text-white/60">{t("projects.new.gitUrl")}</span>
            <input className="input w-full font-mono" value={gitUrl} onChange={(e) => setGitUrl(e.target.value)} placeholder="https://github.com/user/repo.git" />
          </label>
        )}
        {jsKind && (
          <label className="block space-y-1 text-xs">
            <span className="text-white/60">{t("projects.new.pkg")}</span>
            <select className="input w-full" value={pkg} onChange={(e) => setPkg(e.target.value)}>
              <option value="npm">npm</option>
              <option value="pnpm">pnpm</option>
              <option value="yarn">yarn</option>
              <option value="bun">bun</option>
            </select>
          </label>
        )}
        {log.length > 0 && (
          <pre className="max-h-40 overflow-auto rounded bg-black/40 p-2 font-mono text-[10px] leading-relaxed text-white/70">{log.join("\n")}</pre>
        )}
        <div className="flex justify-end gap-2 pt-1">
          <button type="button" onClick={onClose} disabled={running} className="rounded-md border border-white/10 px-3 py-1.5 text-xs text-white/70 hover:bg-white/10 disabled:opacity-40">
            {t("dialog.close")}
          </button>
          <button type="button" disabled={running || !name.trim()} onClick={() => void submit()} className="rounded-md bg-accent px-4 py-1.5 text-xs font-medium text-white disabled:opacity-40">
            {running ? t("projects.new.running") : t("projects.new.create")}
          </button>
        </div>
      </section>
    </div>
  );
}

// VhostModal hand-edits the project's rendered nginx config; re-applying
// the project from its card regenerates the managed render.
function VhostModal({
  name,
  content,
  dirty,
  onChange,
  onClose,
}: {
  name: string;
  content: string;
  dirty: boolean;
  onChange: (content: string) => void;
  onClose: () => void;
}) {
  const t = useT();
  const dialogs = useDialogs();
  const [saving, setSaving] = useState(false);

  const save = async () => {
    setSaving(true);
    try {
      await SaveProjectVhost(name, content);
      onClose();
    } catch (error) {
      await dialogs.alert({ title: name, message: String(error) });
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50" onClick={onClose}>
      <section className="glass flex h-[70vh] w-[760px] max-w-[94vw] flex-col overflow-hidden rounded-xl" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between border-b border-white/10 px-4 py-2.5">
          <span className="font-mono text-xs text-white/70">
            {name}.conf{dirty ? " •" : ""}
          </span>
          <div className="flex gap-2">
            <button type="button" disabled={!dirty || saving} onClick={() => void save()} className="rounded bg-accent px-3 py-1 text-xs font-medium text-white disabled:opacity-40">
              {t("projects.vhost.save")}
            </button>
            <button type="button" onClick={onClose} className="rounded border border-white/10 px-3 py-1 text-xs text-white/60 hover:bg-white/10">
              {t("dialog.close")}
            </button>
          </div>
        </div>
        <p className="px-4 py-1.5 text-[10px] text-white/40">{t("projects.vhost.hint")}</p>
        <div className="min-h-0 flex-1">
          <DocumentEditor value={content} language="nginx" onChange={onChange} onSave={save} />
        </div>
      </section>
    </div>
  );
}


// ExtensionsModal manages one PHP series' extensions: ini state, live
// load state, and availability of the shipped DLL.
function ExtensionsModal({ series, onClose }: { series: string; onClose: () => void }) {
  const t = useT();
  const dialogs = useDialogs();
  const [rows, setRows] = useState<
    { name: string; enabled: boolean; shipped: boolean; loaded: boolean }[]
  >([]);
  const [filter, setFilter] = useState("");
  const [busy, setBusy] = useState("");

  const refresh = useCallback(() => {
    ListPhpExtensions(series)
      .then((list) => setRows(list ?? []))
      .catch(() => setRows([]));
  }, [series]);

  useEffect(() => {
    const timer = setTimeout(() => refresh(), 0);
    return () => clearTimeout(timer);
  }, [refresh]);

  const toggle = async (row: { name: string; enabled: boolean; shipped: boolean }) => {
    setBusy(row.name);
    try {
      await SetPhpExtension(series, row.name, !row.enabled);
      refresh();
    } catch (error) {
      await dialogs.alert({ title: row.name, message: String(error) });
    } finally {
      setBusy("");
    }
  };

  const visible = rows.filter((row) =>
    filter.trim() === "" ? true : row.name.includes(filter.trim().toLowerCase())
  );

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50" onClick={onClose}>
      <section className="glass flex h-[70vh] w-[560px] max-w-[92vw] flex-col overflow-hidden rounded-xl" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between border-b border-white/10 px-4 py-2.5">
          <span className="text-sm font-semibold text-white/90">
            {t("projects.extensions.title")} · PHP {series}
          </span>
          <button type="button" onClick={onClose} className="rounded border border-white/10 px-3 py-1 text-xs text-white/60 hover:bg-white/10">
            {t("dialog.close")}
          </button>
        </div>
        <div className="border-b border-white/5 px-4 py-2">
          <input
            className="input w-full py-1 text-xs"
            placeholder={t("projects.extensions.filter")}
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
          />
        </div>
        <div className="min-h-0 flex-1 overflow-y-auto p-2">
          {visible.map((row) => (
            <div key={row.name} className="flex items-center gap-2 rounded px-2 py-1.5 hover:bg-white/5">
              <button
                type="button"
                disabled={busy === row.name || (!row.enabled && !row.shipped)}
                title={!row.shipped && !row.enabled ? t("projects.extensions.unshipped") : row.loaded ? t("projects.extensions.loaded") : ""}
                onClick={() => void toggle(row)}
                className={`flex h-4 w-7 shrink-0 items-center rounded-full border px-0.5 transition-colors ${
                  row.enabled ? "border-emerald-400/60 bg-emerald-400/20" : "border-white/20 bg-white/5"
                } ${busy === row.name ? "opacity-40" : ""}`}
              >
                <span
                  className={`h-3 w-3 rounded-full transition-transform ${row.enabled ? "translate-x-3 bg-emerald-300" : "bg-white/40"}`}
                />
              </button>
              <span className={`min-w-0 flex-1 truncate font-mono text-xs ${row.enabled ? "text-white/85" : "text-white/45"}`}>
                {row.name}
              </span>
              {row.loaded && (
                <span className="shrink-0 rounded-full border border-emerald-400/30 px-1.5 text-[9px] text-emerald-300">
                  {t("projects.extensions.loaded")}
                </span>
              )}
              {!row.shipped && (
                <span className="shrink-0 rounded-full border border-white/10 px-1.5 text-[9px] text-white/35">
                  {t("projects.extensions.unshipped")}
                </span>
              )}
            </div>
          ))}
          {visible.length === 0 && (
            <p className="px-3 py-6 text-center text-xs text-white/40">{t("projects.extensions.empty")}</p>
          )}
        </div>
      </section>
    </div>
  );
}
